// Interactions: the E-key action at whichever station the cook stands near. This module
// owns pickup/place logic for pantry, chopping block, stoves, plate pass and window.

import { KEY_INTERACT } from './config.js';
import { addPartToPlate, clearPlate, penalizeBurn, servePlate } from './assembly.js';
import { INGREDIENT_KINDS, CHOPPABLE, COOKABLE } from './ingredients.js';
import { nearestStation } from './stations.js';
import { clearBurner, liftFromBurner, placeOnBurner } from './stove.js';
import { pushToast } from './world.js';

/** Everything the cook can do with E, dispatched by the station they stand at. */
export function interactAtStation(world) {
  const player = world.player;
  const station = nearestStation(player.x, player.y, 90);
  if (!station) return 0;
  switch (station) {
    case 'orderBoard':
      return 0; // board is read-only; tickets are picked up by matching, not by hand
    case 'prepBoard':
      return 0;
    case 'choppingBlock':
      return interactChoppingBlock(world);
    case 'stoveLeft':
      return interactStove(world, 0);
    case 'stoveRight':
      return interactStove(world, 1);
    case 'platingCounter':
      return interactPlating(world);
    case 'servingWindow':
      return servePlate(world);
    default:
      return 0;
  }
}

/** E at the pantry strip: pick up the nearest raw ingredient (unless hands are full). */
export function pickFromPantry(world, ingredientKey) {
  if (world.player.carry) {
    pushToast(world, 'Hands full!');
    return 0;
  }
  if (!INGREDIENT_KINDS[ingredientKey]) return 0;
  world.player.carry = ingredientKey;
  return 0;
}

/** E at the chopping block: place carry, or pick up the finished chop. */
function interactChoppingBlock(world) {
  const cutting = world.cutting;
  const carry = world.player.carry;
  if (cutting.ready) {
    if (world.player.carry) {
      pushToast(world, 'Hands full!');
      return 0;
    }
    world.player.carry = cutting.ready;
    cutting.ready = null;
    return 0;
  }
  if (cutting.held) {
    pushToast(world, 'Still chopping — hold E!');
    return 0;
  }
  if (carry && CHOPPABLE.includes(carry)) {
    cutting.held = carry;
    cutting.progress = 0.0001;
    world.player.carry = null;
    return 0;
  }
  if (carry) pushToast(world, 'That needs no chopping.');
  return 0;
}

/** E at a stove: put a cookable on, lift a done dish, or bin a burnt pan. */
function interactStove(world, burnerIndex) {
  const burner = world.burners[burnerIndex];
  const carry = world.player.carry;
  if (burner.occupant && burner.burnt) {
    clearBurner(world, burnerIndex);
    penalizeBurn(world);
    return 0;
  }
  if (burner.occupant && burner.progress >= 1) {
    const cooked = liftFromBurner(world, burnerIndex);
    if (cooked) {
      if (world.player.carry) {
        pushToast(world, 'Hands full!');
        placeOnBurner(world, burnerIndex, cooked.slice(0, -'Cooked'.length));
        // Restore done state instantly (rare hands-full case).
        const b = world.burners[burnerIndex];
        b.progress = 1;
        b.grace = 99;
        return 0;
      }
      world.player.carry = cooked;
      pushToast(world, 'Picked up the pan.');
      return 0;
    }
    return 0;
  }
  if (!burner.occupant && carry && COOKABLE.includes(carry)) {
    world.player.carry = null;
    placeOnBurner(world, burnerIndex, carry);
    pushToast(world, 'On the stove!');
    return 0;
  }
  if (!burner.occupant && carry) pushToast(world, 'That cannot be cooked.');
  if (burner.occupant && burner.progress < 1) pushToast(world, 'Still cooking...');
  return 0;
}

/** E at the plating pass: stack the carried part, or wipe the plate with trash. */
function interactPlating(world) {
  const carry = world.player.carry;
  if (carry && carry.endsWith('Chopped') || carry && carry.endsWith('Cooked') || carry === 'cheese') {
    addPartToPlate(world, carry);
    world.player.carry = null;
    pushToast(world, 'Plated.');
    return 0;
  }
  if (carry) {
    pushToast(world, 'Prep it first (chop or cook).');
    return 0;
  }
  if (world.plate.parts.length > 0) {
    clearPlate(world);
    pushToast(world, 'Plate wiped clean.');
    return 0;
  }
  return 0;
}

/** Human-readable hint of what E would do right now (shown above the cook). */
export function currentHint(world) {
  const player = world.player;
  const station = nearestStation(player.x, player.y, 90);
  const carry = player.carry;
  if (!station) return carry ? `carrying ${carry}` : null;
  switch (station) {
    case 'choppingBlock':
      if (world.cutting.ready) return 'E: take chopped';
      if (world.cutting.held) return 'hold E: chop';
      if (carry && CHOPPABLE.includes(carry)) return 'E: place to chop';
      return 'chopping block';
    case 'stoveLeft':
    case 'stoveRight': {
      const burner = world.burners[station === 'stoveLeft' ? 0 : 1];
      if (burner.burnt) return 'E: bin burnt pan';
      if (burner.occupant && burner.progress >= 1) return 'E: take pan';
      if (burner.occupant) return 'cooking...';
      if (carry && COOKABLE.includes(carry)) return 'E: cook it';
      return 'stove';
    }
    case 'platingCounter':
      if (carry) return 'E: plate it';
      if (world.plate.parts.length) return 'E: wipe plate';
      return 'plating pass';
    case 'servingWindow':
      if (world.plate.parts.length) return 'E: serve!';
      return 'service window';
    default:
      return null;
  }
}
```

### game/src/assembly.js (79 lines, 3033 bytes)

```js
// Plate assembly and serving: stacking prepped parts on the plate, matching against the
// order board, and scoring with the combo streak. One job — turning prepared food into points.

import { SCORE_BURN_PENALTY, SCORE_COLD_PENALTY, SCORE_PER_COMBO, SCORE_PER_ORDER } from './config.js';
import { EVENT_COLD, EVENT_SERVE, pushEffect, pushToast } from './world.js';
import { findMatchingOrder, removeOrder } from './orders.js';
import { COMBO_TIERS } from './config.js';

/** Add a prepped part to the plate (order of stacking is the plate's look). */
export function addPartToPlate(world, partKey) {
  world.plate.parts.push(partKey);
  world.plate.ready = world.plate.parts.length > 0;
}

/** Clear the plate completely (after serving or a wrong plate). */
export function clearPlate(world) {
  world.plate.parts = [];
  world.plate.ready = false;
}

/** Current combo tier label for the HUD. */
export function comboLabel(combo) {
  let label = COMBO_TIERS[0].label;
  for (const tier of COMBO_TIERS) {
    if (combo >= tier.at) label = tier.label;
  }
  return label;
}

/** Multiplier the combo earns on each serve (1 + 0.1 per streak step, capped at 2). */
export function comboMultiplier(combo) {
  return Math.min(2, 1 + combo * 0.1);
}

/**
 * Try to serve the current plate at the service window. Returns an event bitmask.
 * A perfect match scores with the combo multiplier; a wrong plate just bounces.
 */
export function servePlate(world) {
  const match = findMatchingOrder(world.board, world.plate.parts);
  if (!match) {
    pushToast(world, 'That is not on any ticket!');
    return 0;
  }
  const events = EVENT_SERVE;
  if (match.cold) {
    world.score = Math.max(0, world.score - SCORE_COLD_PENALTY);
    world.combo = 0;
    pushToast(world, `${match.name} went cold...`);
    pushEffect(world, { x: world.player.x, y: world.player.y - 50, text: `-${SCORE_COLD_PENALTY}`, fade: 1 });
    world.board.coldCount += 1;
  } else {
    const points = Math.round((SCORE_PER_ORDER + SCORE_PER_COMBO * match.parts.length) * comboMultiplier(world.combo));
    world.score += points;
    world.combo += 1;
    world.bestCombo = Math.max(world.bestCombo, world.combo);
    pushToast(world, `${match.name} served! +${points}`);
    pushEffect(world, { x: world.player.x, y: world.player.y - 50, text: `+${points}`, fade: 0.9 });
  }
  world.board.servedCount += 1;
  removeOrder(world.board, match.id);
  clearPlate(world);
  return events;
}

/** Penalize throwing away a burnt pan. */
export function penalizeBurn(world) {
  world.score = Math.max(0, world.score - SCORE_BURN_PENALTY);
  world.combo = 0;
  pushToast(world, `Burned pan binned. -${SCORE_BURN_PENALTY}`);
  pushEffect(world, { x: world.player.x, y: world.player.y - 50, text: `-${SCORE_BURN_PENALTY}`, fade: 1 });
}

/** A ticket that fully expired was removed by the board; account for it here. */
export function noteColdTicket(world) {
  world.combo = 0;
  pushEffect(world, { x: 200, y: 230, text: 'ticket cold!', fade: 1 });
  return EVENT_COLD;
}
```

### game/src/world.js (159 lines, 4984 bytes)

```js
// Kitchen state and the shift loop: the player, the cutting block, two stoves, the plate
// being assembled, and the shift clock. World holds state; the rules live in stations.js
// (interactions) and assembly.js (plate scoring), so each file has one clear job.

import { SHIFT_SECONDS } from './config.js';
import { createRandom } from './random.js';
import { createOrderBoard, difficultyTierFor, updateOrderBoard } from './orders.js';
import { PLAYER_START } from './stations.js';
import { updateBurners } from './stove.js';

/** The two stove burners start empty. */
function createBurner() {
  return { occupant: null, progress: 0, burnt: false };
}

/** One full fresh world. `seed` keeps screenshot scenes reproducible. */
export function createWorld(seed) {
  return {
    seed,
    screen: 'title',
    paused: false,
    time: 0,
    elapsed: 0,
    score: 0,
    combo: 0,
    bestCombo: 0,
    board: createOrderBoard(createRandom(seed)),
    player: { x: PLAYER_START.x, y: PLAYER_START.y, carry: null, facing: 1, walkPhase: 0 },
    cutting: { held: null, progress: 0, ready: null },
    burners: [createBurner(), createBurner()],
    plate: { parts: [], ready: false },
    trashFlash: 0,
    toast: null,
    toastTimer: 0,
    effects: [],
  };
}

/** Reset everything for a brand new shift. */
export function resetWorld(world) {
  const fresh = createWorld(world.seed);
  Object.assign(world, fresh);
  world.screen = 'play';
}

/** Show a short HUD toast message ("Sun Tomato Bite served!"). */
export function pushToast(world, text) {
  world.toast = text;
  world.toastTimer = 2.4;
}

/** Spawn a floating effect particle (steam puff, spark, score pop). */
export function pushEffect(world, effect) {
  world.effects.push({ life: 1, ...effect });
}

/** Events the main loop turns into sounds and score changes. */
export const EVENT_SERVE = 1;
export const EVENT_BURN = 2;
export const EVENT_COLD = 4;
export const EVENT_CHOP = 8;
export const EVENT_DONE = 16;

/**
 * Advance the world one fixed step with the current input snapshot. Returns an event
 * bitmask (EVENT_* above) so audio.js can react without knowing the rules.
 */
export function stepWorld(world, dt, input, interactPressed) {
  let events = 0;
  world.time += dt;
  if (world.screen !== 'play' || world.paused) return events;

  world.elapsed += dt;
  if (world.elapsed >= SHIFT_SECONDS) {
    world.screen = 'over';
    return events;
  }

  events |= updateOrderBoard(world.board, world.elapsed, dt);
  events |= updatePlayer(world, dt, input);
  events |= updateChopping(world, dt, input, interactPressed);
  events |= updateBurners(world, dt);
  updateEffects(world, dt);
  updateToast(world, dt);
  return events;
}

/** Player movement and facing; carrying does not slow the cook down. */
function updatePlayer(world, dt, input) {
  const player = world.player;
  const speed = 260;
  let vx = 0;
  let vy = 0;
  if (input.left) vx -= 1;
  if (input.right) vx += 1;
  if (input.up) vy -= 1;
  if (input.down) vy += 1;
  if (vx !== 0 || vy !== 0) {
    const len = Math.hypot(vx, vy);
    player.x += (vx / len) * speed * dt;
    player.y += (vy / len) * speed * dt;
    player.walkPhase += dt * 10;
    if (vx !== 0) player.facing = vx > 0 ? 1 : -1;
  }
  player.x = Math.max(50, Math.min(1230, player.x));
  player.y = Math.max(420, Math.min(560, player.y));
  return 0;
}

/**
 * Chopping block: standing at the block with a raw choppable ingredient and holding
 * interact fills the chop progress; finishing flips it to the chopped state.
 */
function updateChopping(world, dt, input, interactPressed) {
  const cutting = world.cutting;
  const player = world.player;
  const atBlock = player.x > 980 && player.x < 1260 && player.y < 560;
  if (cutting.held && atBlock && input.interact) {
    cutting.progress = Math.min(1, cutting.progress + dt / 2.2);
    if (cutting.progress >= 1) {
      cutting.ready = `${cutting.held}Chopped`;
      cutting.held = null;
      cutting.progress = 0;
      pushToast(world, 'Chopped and ready!');
      pushEffect(world, { x: player.x, y: player.y - 40, text: '+chop', fade: 1.4 });
      return EVENT_CHOP;
    }
  } else if (!cutting.held && cutting.progress > 0) {
    cutting.progress = 0;
  }
  return 0;
}

/** Effects fade and drift upward. */
function updateEffects(world, dt) {
  for (const effect of world.effects) {
    effect.life -= dt * (effect.fade ?? 1);
    if (effect.rise) effect.y -= effect.rise * dt;
  }
  world.effects = world.effects.filter((effect) => effect.life > 0);
}

/** Toast timer. */
function updateToast(world, dt) {
  if (world.toastTimer > 0) {
    world.toastTimer -= dt;
    if (world.toastTimer <= 0) world.toast = null;
  }
}

/** Difficulty tier of the current moment, for HUD. */
export function currentDifficulty(world) {
  return difficultyTierFor(world.elapsed);
}

/** Seconds left in the shift. */
export function shiftSecondsLeft(world) {
  return Math.max(0, SHIFT_SECONDS - world.elapsed);
}
